using System.Globalization;

namespace Franca.Services;

// UI 文案：全部硬编码在代码里，英语兜底；语言码与 AppSettings.Languages 一致
// 专有名词（端点名、引擎名、BepInEx/XUnity 等）不翻译
public static class UiStrings
{
    public static string Current { get; set; } = "en";

    public static string Get(string key) => GetForLanguage(Current, key);

    public static string GetForLanguage(string language, string key) =>
        Table.TryGetValue(language, out var lang) && lang.TryGetValue(key, out var value)
            ? value
            : Table["en"].TryGetValue(key, out var fallback) ? fallback : key;

    public static string Format(string key, params object?[] args) => string.Format(Get(key), args);

    public static string FormatForLanguage(string language, string key, params object?[] args) =>
        string.Format(GetForLanguage(language, key), args);

    public static string GetForSystem(string key) =>
        GetForLanguage(AppSettings.ResolveSupportedLanguage(CultureInfo.CurrentUICulture), key);

    public static string FormatForSystem(string key, params object?[] args) => string.Format(GetForSystem(key), args);

    // 启动自检：列出 "语言:key" 形式的缺失项；返回空表示 15 种语言全部写全
    public static IEnumerable<string> MissingKeys()
    {
        foreach (var (lang, entries) in Table)
        foreach (var key in Table["en"].Keys)
            if (!entries.ContainsKey(key))
                yield return $"{lang}:{key}";
    }

